metadata.ans:document:
{
  "format": "ariadne-nsd",
  "version": 1,
  "settings": {
    "textKind": "plain",
    "theme": "default",
    "headStyle": "title",
    "locale": "ko"
  },
  "diagrams": [
    {
      "id": "d1",
      "head": {
        "kind": "method",
        "text": "knapsack(w, v, W)"
      },
      "body": [
        {
          "id": "b1",
          "kind": "process",
          "text": "n = len(w)"
        },
        {
          "id": "b2",
          "kind": "process",
          "text": "dp = [[0] * (W + 1) for _ in range(n + 1)]    # 앞 i개로 무게 c까지 담는 최대 가치"
        },
        {
          "id": "b3",
          "kind": "for",
          "text": "for i in range(1, n + 1)",
          "body": [
            {
              "id": "b4",
              "kind": "for",
              "text": "for c in range(W + 1)",
              "body": [
                {
                  "id": "b5",
                  "kind": "process",
                  "text": "dp[i][c] = dp[i - 1][c]    # i번째를 넣지 않는다"
                },
                {
                  "id": "b6",
                  "kind": "if",
                  "text": "w[i - 1] <= c",
                  "yes": {
                    "id": "r1",
                    "body": [
                      {
                        "id": "b7",
                        "kind": "process",
                        "text": "take = dp[i - 1][c - w[i - 1]] + v[i - 1]    # i번째를 넣는다"
                      },
                      {
                        "id": "b8",
                        "kind": "if",
                        "text": "take > dp[i][c]",
                        "yes": {
                          "id": "r2",
                          "body": [
                            {
                              "id": "b9",
                              "kind": "process",
                              "text": "dp[i][c] = take"
                            }
                          ]
                        },
                        "no": {
                          "id": "r3",
                          "body": [
                            {
                              "id": "b10",
                              "kind": "process",
                              "text": ""
                            }
                          ]
                        }
                      }
                    ]
                  },
                  "no": {
                    "id": "r4",
                    "body": [
                      {
                        "id": "b11",
                        "kind": "process",
                        "text": ""
                      }
                    ]
                  }
                }
              ]
            }
          ]
        },
        {
          "id": "b12",
          "kind": "process",
          "text": "items, c = [], W"
        },
        {
          "id": "b13",
          "kind": "for",
          "text": "for i in range(n, 0, -1)",
          "body": [
            {
              "id": "b14",
              "kind": "if",
              "text": "dp[i][c] != dp[i - 1][c]",
              "yes": {
                "id": "r5",
                "body": [
                  {
                    "id": "b15",
                    "kind": "process",
                    "text": "items.append(i - 1)    # 이 물건을 넣었다"
                  },
                  {
                    "id": "b16",
                    "kind": "process",
                    "text": "c -= w[i - 1]"
                  }
                ]
              },
              "no": {
                "id": "r6",
                "body": [
                  {
                    "id": "b17",
                    "kind": "process",
                    "text": ""
                  }
                ]
              }
            }
          ]
        },
        {
          "id": "b18",
          "kind": "process",
          "text": "return dp[n][W], items"
        }
      ],
      "folds": [
        {
          "id": "f1",
          "first": "b3",
          "last": "b3",
          "name": "표 채우기"
        },
        {
          "id": "f2",
          "first": "b12",
          "last": "b13",
          "name": "고른 물건 되짚기"
        }
      ]
    }
  ],
  "view": {
    "folded": [],
    "opened": [],
    "bands": true,
    "resultSymbol": "←"
  }
}
